CREATE TABLE t(a INTEGER, b TEXT, c REAL, f);
INSERT INTO t VALUES (1, '1', 1.0, 1), (2, '10', 2.5, '2'), (3, 'abc', 3.0, 'x'), (5, '5', 5.0, 5);
CREATE TABLE u(x INTEGER, y TEXT);
INSERT INTO u VALUES (1, '1'), (5, '5'), (10, '10');
SELECT t.a, u.x FROM t JOIN u ON t.a = u.y;
SELECT t.a, u.x FROM t JOIN u ON t.b = u.x;
SELECT t.a, u.x FROM t, u WHERE t.b = u.x;
SELECT t.a, u.x FROM t LEFT JOIN u ON u.y = t.a;
SELECT a FROM t WHERE +a = '1';
SELECT a FROM t WHERE a = '1' || '';
SELECT a FROM t WHERE a = (b || '');
SELECT a FROM t WHERE b = a + 0;
SELECT a FROM t WHERE b = (a + 0);
SELECT a FROM t WHERE f = a;
SELECT a FROM t WHERE f = '1';
SELECT a FROM t WHERE f = 1;
SELECT a FROM t WHERE f > b;
SELECT a FROM t WHERE c = b;
SELECT a FROM t WHERE likely(a) = '1';
SELECT a FROM t WHERE a IN (SELECT y FROM u);
SELECT a FROM t WHERE b IN (SELECT x FROM u);
SELECT a FROM t WHERE a = (SELECT y FROM u WHERE x = 5);
SELECT a, (SELECT count(*) FROM u WHERE u.y = t.a) FROM t;
SELECT a FROM t WHERE EXISTS (SELECT 1 FROM u WHERE u.y = t.a);
SELECT a FROM t WHERE a BETWEEN '1' AND b;
SELECT a FROM t WHERE CAST(a AS TEXT) = 1;
SELECT a FROM t WHERE CAST(a AS TEXT) < 2;
SELECT a FROM t WHERE CAST(b AS INTEGER) = '10';
SELECT x FROM u WHERE y > 2;
SELECT x FROM u WHERE y > '2';
CREATE INDEX uy ON u(y);
SELECT x FROM u WHERE y = 5;
SELECT x FROM u WHERE y > 2;
SELECT x FROM u WHERE y IN (1, 10);
CREATE INDEX ta ON t(a);
SELECT a FROM t WHERE a = '5';
SELECT a FROM t WHERE a IN ('1', '5');
SELECT a FROM t WHERE a > '2';
SELECT t.a FROM u JOIN t ON t.a = u.y;
